const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-adapter');
const { Redis } = require('ioredis');
const jwt = require('jsonwebtoken');
const { CareTeamService } = require('../services/careTeam');

const server = http.createServer();
const io = new Server(server);

const pub = new Redis(process.env.REDIS_URL);
const sub = pub.duplicate();
io.adapter(createAdapter(pub, sub));

const telemetryNsp = io.of(/^\/telemetry\/patient-[0-9]+$/);

telemetryNsp.use(async (socket, next) => {
  const token = socket.handshake.auth.staffToken;
  if (!token) return next(new Error('Medical staff token required'));

  try {
    const payload = jwt.verify(token, process.env.STAFF_JWT_KEY);
    if (payload.role !== 'NURSE' && payload.role !== 'DOCTOR') {
      return next(new Error('Unauthorized clinical role'));
    }

    const patientId = socket.nsp.name.split('-')[1];

    // Enforce patient-to-provider assignment before permitting namespace connection
    const isAssigned = await CareTeamService.isStaffAssignedToPatient(payload.staffId, patientId);
    if (!isAssigned) {
      return next(new Error('Access denied: clinician not assigned to patient telemetry unit'));
    }

    socket.staff = payload;
    next();
  } catch {
    next(new Error('Authorization verification failed'));
  }
});

telemetryNsp.on('connection', (socket) => {
  const patientId = socket.nsp.name.split('-')[1];

  socket.on('subscribe_vitals', () => {
    socket.emit('vital_stream_active', { patientId, streamUrl: `/streams/icu/${patientId}` });
  });
});

server.listen(4004);
